  assert(names.every(n=>['REPORT.md','RESEARCH.md','streams','state.json','support'].includes(n)), names.join(', '));
  const report = readFileSync(join(run,'REPORT.md'),'utf8');
  const research = readFileSync(join(run,'RESEARCH.md'),'utf8');
